Lemma node_kit_cfg : forall ms mo x8 (P : resp -> Model -> list event -> Prop),
  ms_svc_pending ms = Some x8 -> m_halted mo = None ->
  (forall eff mo' evs, check_syscall (sys_input segs ms x8) eff mo = CheckOk mo' evs ->
     ~ spurious_refusal_cfg ACFG (sys_input segs ms x8) mo eff -> P (rstrip eff) mo' evs) ->
  (forall eff mo' evs, P eff mo' evs ->
     exists effk, check_syscall (sys_input segs ms x8) effk mo = CheckOk mo' evs /\ rstrip effk = eff
                  /\ ~ spurious_refusal_cfg ACFG (sys_input segs ms x8) mo effk) ->
  (forall eff, check_syscall (sys_input segs ms x8) eff mo <> CheckUnmodeled) ->
  (forall eff mo' evs, check_syscall (sys_input segs ms x8) eff mo = CheckOk mo' evs -> m_halted mo' = None) ->
  (forall eff mo' evs, P eff mo' evs -> m_halted mo' = None /\ m_vm_lazy mo' = []) ->
  (forall evs X, sstep_cfg segs ACFG (mkCfg ms mo) evs X ->
     exists eff mo', X = SNext (mkCfg (nret ms eff) mo') /\ P eff mo' evs)
  /\ (forall eff mo' evs, P eff mo' evs -> sstep_cfg segs ACFG (mkCfg ms mo) evs (SNext (mkCfg (nret ms eff) mo')))
  /\ (exists eff mo' evs, P eff mo' evs).
Proof.
  intros ms mo x8 P Hsvc Hh Hsnd Hcpl Hnu Hnh Hhalt. split; [|split].
  - intros evs X Hst. destruct (sstep_cfg_svc_inv _ _ _ _ _ Hsvc Hst)
      as [(eff & mo' & mo'' & Hs & Hns & Hh' & Hmat & ->) | [(eff & mo' & evs1 & Hs & Hns & Hh' & Hmat & -> & ->)
         | [(eff & mo' & evs0 & code & Hs & Hh' & Hk' & -> & ->) | [(eff & mo' & evs0 & sig & Hs & Hk' & -> & ->) | (Hs & -> & ->)]]]].
    + exists (rstrip eff), mo'. apply check_syscall_ok_iff in Hs. pose proof (Hsnd _ _ _ Hs Hns) as HP.
      rewrite (materialize_model_accesses_no_lazy mo' _ (proj2 (Hhalt _ _ _ HP))) in Hmat. inversion Hmat; subst.
      rewrite nret_rstrip. split; [reflexivity| exact HP].
    + exfalso. apply check_syscall_ok_iff in Hs. pose proof (Hsnd _ _ _ Hs Hns) as HP.
      rewrite (materialize_model_accesses_no_lazy mo' _ (proj2 (Hhalt _ _ _ HP))) in Hmat. discriminate.
    + exfalso. apply check_syscall_ok_iff in Hs. apply Hnh in Hs. congruence.
    + exfalso. apply check_syscall_ok_iff in Hs. apply Hnh in Hs. exact (m_killed_halted _ _ Hk' Hs).
    + exfalso. apply (check_syscall_complete_unmodeled _ _ (eff0 (Z_to_bv 64 0))) in Hs. exact (Hnu _ Hs).
  - intros eff mo' evs HP. destruct (Hhalt _ _ _ HP) as [Hh' Hlz].
    destruct (Hcpl _ _ _ HP) as (effk & Hck & Hst & Hns). rewrite <- Hst, nret_rstrip. unfold nret.
    eapply sstep_cfg_syscall; [exact Hh|exact Hsvc| apply check_syscall_ok_iff; exact Hck | exact Hns
                              | exact Hh'| apply materialize_model_accesses_no_lazy; exact Hlz].
  - pose proof (receptive (sys_input segs ms x8) mo) as Hr.
    destruct (syscall_spec_witness (sys_input segs ms x8) mo) as [eff0' mo0 evs0|] eqn:E.
    + destruct (exists_nonspurious ACFG _ _ _ _ _ Hr) as (eff & mo' & evs & Hs & Hns).
      exists (rstrip eff), mo', evs. apply Hsnd; [apply check_syscall_ok_iff; exact Hs| exact Hns].
    + exfalso. apply (check_syscall_complete_unmodeled _ _ (eff0 (Z_to_bv 64 0))) in Hr. exact (Hnu _ Hr).
Qed.

(* [comment removed for export] *)
Lemma node_kit_strict : forall ms mo x8 (P : resp -> Model -> list event -> Prop),
  ms_svc_pending ms = Some x8 -> m_halted mo = None ->
  (forall eff mo' evs, check_syscall (sys_input segs ms x8) eff mo = CheckOk mo' evs <-> P eff mo' evs) ->
  (forall eff mo' evs, P eff mo' evs -> rstrip eff = eff) ->
  (forall eff, check_syscall (sys_input segs ms x8) eff mo <> CheckUnmodeled) ->
  (forall eff mo' evs, P eff mo' evs -> m_halted mo' = None /\ m_vm_lazy mo' = []) ->
  (forall evs X, sstep segs (mkCfg ms mo) evs X ->
     exists eff mo', X = SNext (mkCfg (nret ms eff) mo') /\ P eff mo' evs)
  /\ (forall eff mo' evs, P eff mo' evs -> sstep segs (mkCfg ms mo) evs (SNext (mkCfg (nret ms eff) mo')))
  /\ (exists eff mo' evs, P eff mo' evs).
Proof.
