Lemma open_result_pres : forall mo ent eff mo',
  minv mo -> m_halted mo = None ->
  open_result mo ent eff mo' ->
  match ent with FdDir => True | FdFile p _ => fs_lookup (m_fs mo) p <> None | _ => False end ->
  m_halted mo' = None /\ minv mo'.
Proof.
