Lemma nonalloc_svc : forall ms K,
  ms_svc_pending ms = Some (Z_to_bv 64 K) -> alloc_no_b (bv_unsigned (Z_to_bv 64 K)) = false ->
  forall x8, ms_svc_pending ms = Some x8 -> ~ In (bv_unsigned x8) alloc_mark_sysnos.
Proof.
  intros ms K Hs Hb x8 Hx. rewrite Hs in Hx. injection Hx as <-. apply alloc_no_b_false. exact Hb.
Qed.

Lemma at_node_nonalloc_svc : forall n ms, alloc_node n = false -> at_node segs n ms ->
  exists x8, ms_svc_pending ms = Some x8 /\ ~ In (bv_unsigned x8) alloc_mark_sysnos.
Proof.
  intros n ms Ha Hat. destruct n; try discriminate Ha; cbn [at_node] in Hat;
    match type of Hat with
    | (ms_svc_pending ms = Some _ \/ _) /\ _ => destruct Hat as [[H|H] _]
    | ms_svc_pending ms = Some _ /\ _ => destruct Hat as [H _]
    | ms_svc_pending ms = Some _ => rename Hat into H
    end;
    (eexists; split; [exact H| apply alloc_no_b_false; vm_compute; reflexivity]).
Qed.

Lemma all_facts : forall n ms mo,
  match n with NExit _ => False | _ => True end ->
  at_node segs n ms -> minv mo -> m_halted mo = None -> nsafe n mo -> node_facts_cfg ms mo n.
Proof.
  intros n ms mo Hne Hat Hminv Hh Hsafe. destruct n; try contradiction.
  - apply node_facts_cfg_of_facts; [apply (nonalloc_svc ms 64); [exact (proj1 Hat)| reflexivity] |].
    apply write_facts; assumption.
  - apply node_facts_cfg_of_facts; [apply (nonalloc_svc ms 66); [exact (proj1 Hat)| reflexivity] |].
    apply writev_facts; assumption.
  - apply node_facts_cfg_of_facts; [apply (nonalloc_svc ms 56); [exact (proj1 Hat)| reflexivity] |].
    apply open_facts; assumption.
  - apply node_facts_cfg_of_facts; [apply (nonalloc_svc ms 63); [exact (proj1 Hat)| reflexivity] |].
    apply read_facts; assumption.
  - apply node_facts_cfg_of_facts; [apply (nonalloc_svc ms 57); [exact (proj1 Hat)| reflexivity] |].
    apply close_facts; assumption.
  - apply node_facts_cfg_of_facts; [apply (nonalloc_svc ms 29); [exact (proj1 Hat)| reflexivity] |].
    apply ioctl_facts; assumption.
  - apply node_facts_cfg_of_facts; [apply (nonalloc_svc ms 96); [exact Hat| reflexivity] |].
    apply set_tid_facts; assumption.
  - apply brk_facts; assumption.
  - apply mmap_facts; assumption.
  - apply node_facts_cfg_of_facts; [apply (nonalloc_svc ms 215); [exact (proj1 Hat)| reflexivity] |].
    apply munmap_facts; assumption.
  - apply mprotect_facts; assumption.
  - apply node_facts_cfg_of_facts; [apply (nonalloc_svc ms 233); [exact (proj1 Hat)| reflexivity] |].
    apply madvise_facts; assumption.
Qed.

